  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen',
    'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue',
    sans-serif;
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
  color: #e0e0e0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.quiz-container {
  max-width: 700px;
  width: 100%;
}

main {
  background: #0f3460;
  border-radius: 12px;
  padding: 40px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
  border: 1px solid rgba(255, 255, 255, 0.1);
}

h1 {
  margin-top: 0;
  margin-bottom: 32px;
  font-size: 28px;
  font-weight: 600;
  color: #00d4ff;
  text-align: center;
}

h2 {
  color: #00d4ff;
  margin-top: 0;
}

form {
  display: flex;
  flex-direction: column;
  gap: 28px;
}

.form-field {
  display: flex;
  flex-direction: column;
}

fieldset {
  margin: 0;
  padding: 0;
  border: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

legend {
  font-size: 16px;
  font-weight: 600;
  color: #ffffff;
  padding: 0;
  margin: 0 0 8px 0;
  display: flex;
  align-items: center;
  gap: 4px;
}

legend span {
  color: #ff6b6b;
}

#q1-help {
  font-size: 14px;
  color: #a0a0a0;
  margin: 8px 0 12px 0;
  line-height: 1.4;
}

.checkbox-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 0;
}

input[type="checkbox"] {
  width: 20px;
  height: 20px;
  cursor: pointer;
  accent-color: #00d4ff;
  min-width: 20px;
}

label {
  cursor: pointer;
  font-size: 15px;
  color: #e0e0e0;
  user-select: none;
  display: inline;
}

input[type="checkbox"]:focus {
  outline: 2px solid #00d4ff;
  outline-offset: 2px;
}

input[type="checkbox"]:hover:not(:disabled) {
  accent-color: #00b8d4;
}

input[type="checkbox"]:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

input[type="checkbox"]:checked {
  accent-color: #00d4ff;
}

#q2-error,
#q3-error {
  font-size: 14px;
  color: #ff6b6b;
  margin-top: 8px;
  line-height: 1.4;
}

.submit-btn {
  background: linear-gradient(135deg, #00d4ff 0%, #0099cc 100%);
  color: #0f3460;
  border: none;
  padding: 12px 28px;
  font-size: 16px;
  font-weight: 600;
  border-radius: 6px;
  cursor: pointer;
  transition: all 0.2s ease;
  margin-top: 8px;
}

.submit-btn:hover {
  background: linear-gradient(135deg, #00e0ff 0%, #00aadd 100%);
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(0, 212, 255, 0.3);
}

.submit-btn:focus {
  outline: 2px solid #00d4ff;
  outline-offset: 2px;
}

.submit-btn:active {
  transform: translateY(0);
}

.result-container {
  background: rgba(0, 212, 255, 0.1);
  border: 1px solid #00d4ff;
  border-radius: 6px;
  padding: 20px;
  margin-top: 24px;
  animation: slideIn 0.3s ease;
}

#result-text {
  font-size: 15px;
  margin: 0;
  color: #e0e0e0;
  line-height: 1.6;
}

@keyframes slideIn {
  from {
    opacity: 0;
    transform: translateY(-10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* Accessibility: Forced colors mode support */
@media (forced-colors: active) {
  input[type="checkbox"] {
    accent-color: CanvasText;
    border: 2px solid CanvasText;
  }

  input[type="checkbox"]:focus {
    outline-color: Highlight;
  }

  .submit-btn {
    background: ButtonFace;
    color: ButtonText;
    border: 2px solid ButtonText;
  }

  .submit-btn:focus {
    outline-color: Highlight;
  }

  legend span {
    color: CanvasText;
  }

  #q2-error,
  #q3-error {
    color: CanvasText;
  }
}

/* Respect reduced motion preference */
@media (prefers-reduced-motion: reduce) {
  * {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

/* Mobile optimization */
@media (max-width: 480px) {
  main {
    padding: 24px;
  }

  h1 {
    font-size: 24px;
    margin-bottom: 24px;
  }

  legend {
    font-size: 15px;
  }

  label {
    font-size: 14px;
  }

  input[type="checkbox"] {
    width: 24px;
    height: 24px;
  }
}
