  const form = document.getElementById('quizForm');
  const resultContainer = document.getElementById('result');
  const resultText = document.getElementById('result-text');

  const correctAnswers = {
    question1: new Set(['python', 'javascript', 'ruby']),
    question2: new Set(['typescript', 'java', 'go']),
    question3: new Set(['java', 'kotlin', 'scala'])
  };

  form.addEventListener('submit', (e) => {
    e.preventDefault();
    resultContainer.hidden = true;

    const formData = new FormData(form);
    const answers = {
      question1: new Set(formData.getAll('question1')),
      question2: new Set(formData.getAll('question2')),
      question3: new Set(formData.getAll('question3'))
    };

    let isValid = true;
    let score = 0;
    const feedback = [];

    for (let i = 1; i <= 3; i++) {
      const questionKey = `question${i}`;
      const userAnswers = answers[questionKey];

      if (userAnswers.size === 0) {
        isValid = false;
        const errorElement = document.getElementById(`q${i}-error`);
        errorElement.textContent = `Error: Please select at least one answer for question ${i}.`;
        errorElement.hidden = false;
      } else {
        const errorElement = document.getElementById(`q${i}-error`);
        errorElement.hidden = true;

        const correct = correctAnswers[questionKey];
        const isAnswerCorrect =
          userAnswers.size === correct.size &&
          Array.from(userAnswers).every(answer => correct.has(answer));

        if (isAnswerCorrect) {
          score++;
          feedback.push(`✓ Question ${i}: Correct!`);
        } else {
          feedback.push(`✗ Question ${i}: Incorrect. Expected: ${Array.from(correct).join(', ')}`);
        }
      }
    }

    if (isValid) {
      const percentage = Math.round((score / 3) * 100);
      resultText.innerHTML = `
        <strong>Score: ${score}/3 (${percentage}%)</strong><br><br>
        ${feedback.join('<br>')}
      `;
      resultContainer.hidden = false;
      resultContainer.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    }
  });
